import '../model/document_dataset.dart';
import '../progress/cancellation_token.dart';
import '../progress/document_progress.dart';
import 'export_definition.dart';

/// Contract implemented by format-specific export adapters (CSV, XLSX, JSON, PDF).
abstract interface class ExportAdapter {
  /// Format identifier (e.g. 'csv', 'xlsx', 'json', 'pdf').
  String get formatId;

  /// Primary file extension (e.g. 'csv').
  String get primaryExtension;

  /// MIME type of generated bytes (e.g. 'text/csv', 'application/json').
  String get mimeType;

  /// Serializes [dataset] according to [definition] into raw bytes.
  Future<List<int>> export(
    DocumentDataset dataset,
    ExportDefinition definition, {
    CancellationToken? cancellationToken,
    DocumentProgressCallback? onProgress,
  });
}
